void example_check_gui_json() {
    Serial.println("=== Example 1: Check GUI JSON Memory ===");
    
    // Check simple GUI
    GuiMemoryStats simple_stats = gui_memory_calculate_from_json(simple_gui_json);
    Serial.print("Simple GUI - Widgets: ");
    Serial.print(simple_stats.widget_count);
    Serial.print(", Memory: ");
    Serial.print(gui_memory_format_size(simple_stats.total_memory_bytes));
    Serial.print(", Fits: ");
    Serial.println(simple_stats.fits_in_memory ? "YES" : "NO");
    
    // Check complex GUI
    GuiMemoryStats complex_stats = gui_memory_calculate_from_json(complex_gui_json);
    Serial.print("Complex GUI - Widgets: ");
    Serial.print(complex_stats.widget_count);
    Serial.print(", Memory: ");
    Serial.print(gui_memory_format_size(complex_stats.total_memory_bytes));
    Serial.print(", Fits: ");
    Serial.println(complex_stats.fits_in_memory ? "YES" : "NO");
}

// ============================================================================
// Example 2: Load GUI with memory checking
// ============================================================================

void example_load_gui_with_check() {
    Serial.println("\n=== Example 2: Load GUI with Memory Check ===");
    
    // Try to load simple GUI
    Serial.println("Loading simple GUI...");
    void* simple_gui = gui_loader_load_with_memory_check(simple_gui_json, tft);
    
    if (simple_gui) {
        Serial.println("Simple GUI loaded successfully!");
        // Use the GUI...
        // When done: free(simple_gui); or use SAFE_RELEASE
    } else {
        Serial.println("Simple GUI failed to load (memory check failed)");
    }
    
    // Try to load complex GUI
    Serial.println("\nLoading complex GUI...");
    void* complex_gui = gui_loader_load_with_memory_check(complex_gui_json, tft);
    
    if (complex_gui) {
        Serial.println("Complex GUI loaded successfully!");
        // Use the GUI...
    } else {
        Serial.println("Complex GUI failed to load (memory check failed)");
    }
}

// ============================================================================
// Example 3: Check current memory usage
// ============================================================================

void example_check_current_memory() {
    Serial.println("\n=== Example 3: Current Memory Usage ===");
    
    GuiMemoryStats current = gui_memory_get_current_usage();
    Serial.print("Currently allocated - Buttons: ");
    Serial.print(current.button_count);
    Serial.print(", Labels: ");
    Serial.print(current.label_count);
    Serial.print(", Sliders: ");
    Serial.print(current.slider_count);
    Serial.print(", Views: ");
    Serial.print(current.view_count);
    Serial.print(", Total Memory: ");
    Serial.println(gui_memory_format_size(current.total_memory_bytes));
}

// ============================================================================
// Example 4: Load from SD card with memory check
// ============================================================================

void example_load_from_sd() {
    Serial.println("\n=== Example 4: Load from SD Card with Memory Check ===");
    
    // Try to load a GUI from SD card
    void* gui = gui_loader_load_sd_with_memory_check("main_gui.json", tft);
    
    if (gui) {
        Serial.println("GUI loaded from SD card successfully!");
        // Use the GUI...
    } else {
        Serial.println("GUI failed to load from SD card (memory check or file not found)");
    }
}

