void example_huge_gui() {
    Serial.println("\n=== Example 5: Huge GUI (Exceeds Memory) ===");
    
    // Check memory requirements
    GuiMemoryStats stats = gui_memory_calculate_from_json(huge_gui_json);
    Serial.print("Huge GUI - Widgets: ");
    Serial.print(stats.widget_count);
    Serial.print(", Memory: ");
    Serial.print(gui_memory_format_size(stats.total_memory_bytes));
    Serial.print(", Fits: ");
    Serial.println(stats.fits_in_memory ? "YES" : "NO");
    
    if (!stats.error_message) {
        Serial.print("Error: ");
        Serial.println(stats.error_message);
    }
    
    // Try to load it (should fail and show error on TFT)
    Serial.println("\nAttempting to load huge GUI...");
    void* huge_gui = gui_loader_load_with_memory_check(huge_gui_json, tft);
    
    if (huge_gui) {
        Serial.println("Huge GUI loaded (unexpected!)");
    } else {
        Serial.println("Huge GUI failed to load as expected (memory check prevented it)");
        Serial.println("Error message should be displayed on TFT");
    }
}

// ============================================================================
// Main Example Setup and Loop
// ============================================================================

void setup_gui_memory_check_example() {
    Serial.begin(115200);
    while (!Serial);
    
    Serial.println("GUIKit Memory Check Example");
    Serial.println("============================");
    
    // Initialize widget pools
    pools_init();
    
    // Initialize memory checker
    gui_memory_checker_init();
    
    // Run examples
    example_check_gui_json();
    example_load_gui_with_check();
    example_check_current_memory();
    
    // For SD card examples, you need to have SD card initialized
    // example_load_from_sd();
    
    example_huge_gui();
    
    Serial.println("\nAll examples completed!");
}

void loop_gui_memory_check_example() {
    // Nothing to do in loop for this example
    delay(1000);
}

// ============================================================================
// Standalone Usage Example
// ============================================================================

/**
 * Example of how to use memory checking in a real application
 */
void application_example() {
    // In your application setup:
    
    // 1. Initialize hardware
    // initHardwareFromUnionConfig();
    
    // 2. Initialize pools
    pools_init();
    
    // 3. Initialize memory checker
    gui_memory_checker_init();
    
    // 4. Load GUI with memory check
    const char* gui_file = "/gui/main_gui.json";
    
    // Option A: Check first, then load
    GuiMemoryStats stats = gui_memory_calculate_from_file(gui_file);
    if (!stats.fits_in_memory) {
        // Display error on TFT
        gui_memory_display_error(tft, &stats);
        // Fallback to a simpler GUI or wait
        return;
    }
    
    // Load the GUI (memory is OK)
    void* gui = gui_loader_load_from_sd(gui_file);
    if (!gui) {
        // Handle other errors (file not found, etc.)
        gui_memory_display_oom_error(tft, "Cannot load GUI file");
        return;
    }
    
    // Option B: Use the memory-safe loader (does both in one call)
    void* gui2 = gui_loader_load_sd_with_memory_check(gui_file, tft);
    if (!gui2) {
        // Memory check failed or file error, error already displayed on TFT
        return;
    }
    
    // Use the GUI...
}
